CREATE TABLE personal_loans (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), person_name VARCHAR(255) NOT NULL, description VARCHAR(500) NOT NULL, original_amount NUMERIC(19,2) NOT NULL, installment_amount NUMERIC(19,2) NOT NULL, installments_total INTEGER NOT NULL, installments_paid INTEGER NOT NULL DEFAULT 0, start_date DATE NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE shared_expenses (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), person_name VARCHAR(255) NOT NULL, description VARCHAR(500) NOT NULL, reference_month VARCHAR(7) NOT NULL, total_amount NUMERIC(19,2) NOT NULL, own_amount NUMERIC(19,2) NOT NULL, counterpart_amount NUMERIC(19,2) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING');
CREATE TABLE exchange_rates (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), reference_month VARCHAR(7) NOT NULL, currency VARCHAR(10) NOT NULL, rate NUMERIC(19,6) NOT NULL, UNIQUE(user_id, reference_month, currency));
